appearance.css:
/* 1920×1080。血液の循環を上段、膜を通る移動を下段に置く。 */
#stage {
  --paper: #fbfcfa;
  --primary: #367f83 !important;
  --accent: #dc866e !important;
  --soft: #e7f1ef !important;
  --marker: #e7f1ef !important;
  --text-strong: #303b3d;
  --text: #626d6e;
  --text-meta: #626d6e;
  --left: 112px;
  --right: 112px;
  --heading: 46px;
  --body: 28px;
}
#stage::before { width: 12px; border: 0; box-shadow: none; }
#stage .slide-header { top: 48px; font-size: 20px; }
#stage #eyebrow { letter-spacing: .12em; }
#stage #brand { font-size: 22px; letter-spacing: .2em; }
#stage #slide-content { top: 120px; bottom: 142px; }
#stage h1 { border: 0; padding: 0 0 30px; margin: 0; line-height: 1.5; letter-spacing: .01em; border-bottom: 2px solid #d9e3df; }
#stage .section-number { display: none; }
#stage strong { color: var(--text-strong); font-weight: 800; }
#stage .layout-flow .blocks { position: relative; display: block; padding: 0; margin: 62px 0 0; height: 540px; flex: none; }
#stage .layout-flow .blocks > .reveal { position: absolute; display: block; grid-row: auto; min-width: 0; }
#stage .layout-flow .blocks > .reveal[data-block="out"] { left: 0; top: 0; width: 392px; }
#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] { left: 552px; top: 0; width: 592px; }
#stage .layout-flow .blocks > .reveal[data-block="return"] { right: 0; top: 0; width: 392px; }
#stage .layout-flow .block-body { height: 230px; min-height: 0; padding: 30px 24px; border: 1.5px solid #c7d7d1; background: transparent; justify-content: center; gap: 18px; text-align: center; }
#stage .layout-flow .block-label { font-size: 32px; font-weight: 800; line-height: 1.5; letter-spacing: .01em; }
#stage .layout-flow .block-text { font-size: 28px; line-height: 1.65; }
#stage .layout-flow .block-detail { font-size: 24px; line-height: 1.6; margin-top: 18px; padding: 0; }
#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] .block-body { background: #e7f1ef; border: 2px solid var(--primary); }
#stage .layout-flow .blocks > .reveal[data-block="return"] .block-body { background: transparent; border: 1.5px solid #c7d7d1; }
#stage .layout-flow .blocks > .reveal + .reveal .block-body::before { left: -136px; top: 111px; width: 108px; height: 5px; background: var(--accent); }
#stage .layout-flow .blocks > .reveal + .reveal .block-body::after { left: -32px; top: 102px; border: 12px solid transparent; border-left: 18px solid var(--accent); border-right: 0; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] { left: 0; right: 0; top: 344px; width: auto; padding: 28px 0 0; border-top: 2px solid #d9e3df; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-body { display: block; height: auto; border: 0; padding: 0; background: transparent; text-align: left; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-body::before { content: none; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-body::after { content: none; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-label { font-size: 24px; font-weight: 700; margin-bottom: 24px; }
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-text { padding-left: 24px; border-left: 6px solid var(--primary); width: 808px; font-size: 30px; line-height: 1.9; }
#stage .slide-note { padding: 22px 0 0; font-size: 28px; line-height: 1.65; border-top: 2px solid var(--primary); color: var(--text-strong); }
#stage .slide-note::before { width: 72px; background: var(--accent); }
#stage .slide-footer { bottom: 46px; border-top: 1px solid #d9e3df; padding-top: 18px; font-size: 20px; }


/* 再生位置から与えられる --draw / --enter を使う。CSS独自の時計は使わない。 */
#stage .motion-flow .blocks > .reveal[data-block="dialyzer"] .block-body::before,
#stage .motion-flow .blocks > .reveal[data-block="return"] .block-body::before { width: calc(108px * var(--draw, 1)); }
#stage .motion-flow .blocks > .reveal[data-block="dialyzer"] .block-body::after,
#stage .motion-flow .blocks > .reveal[data-block="return"] .block-body::after { left: calc(-136px + 104px * var(--draw, 1)); opacity: calc(var(--draw, 1) * 100); }
#stage .layout-flow .blocks > .reveal[data-block="ultrafiltration"] { left: 864px; top: 434px; width: 832px; }
#stage .layout-flow .blocks > .reveal[data-block="ultrafiltration"] .block-body { display: block; height: auto; min-height: 0; padding: 0; border: 0; background: transparent; text-align: left; }
#stage .layout-flow .blocks > .reveal[data-block="ultrafiltration"] .block-body::before,
#stage .layout-flow .blocks > .reveal[data-block="ultrafiltration"] .block-body::after { content: none; }
#stage .layout-flow .blocks > .reveal[data-block="ultrafiltration"] .block-text { padding-left: 24px; border-left: 6px solid var(--accent); font-size: 30px; line-height: 1.9; }
#stage .motion-flow .blocks > .reveal[data-block="diffusion"] .block-text,
#stage .motion-flow .blocks > .reveal[data-block="ultrafiltration"] .block-text { position: relative; padding-bottom: 8px; background-image: linear-gradient(var(--soft), var(--soft)); background-position: left bottom; background-repeat: no-repeat; background-size: calc(var(--enter, 1) * 100%) 4px; }
#stage .motion-flow .blocks > .reveal[data-block="diffusion"] .block-text::after,
#stage .motion-flow .blocks > .reveal[data-block="ultrafiltration"] .block-text::after { content: ''; position: absolute; width: 14px; height: 14px; border-radius: 50%; background: var(--accent); bottom: 0; left: calc(var(--enter, 1) * 92%); opacity: calc(4 * var(--enter, 1) * (1 - var(--enter, 1))); }

/* ==========================================================================
   血液透析の仕組み（Antigravity Exclusive Design & Animation）
   ========================================================================== */

@keyframes pulse-dialyzer {
  0%, 100% {
    box-shadow: 0 14px 36px rgba(0, 118, 133, 0.12), 0 0 0 1.5px rgba(0, 172, 193, 0.35);
  }
  50% {
    box-shadow: 0 18px 44px rgba(0, 118, 133, 0.22), 0 0 0 3px rgba(0, 172, 193, 0.65);
  }
}

@keyframes blood-pulse {
  0%, 100% {
    filter: drop-shadow(0 2px 6px rgba(211, 47, 47, 0.25));
  }
  50% {
    filter: drop-shadow(0 4px 12px rgba(211, 47, 47, 0.45));
  }
}

@keyframes diffuse-shimmer {
  0%, 100% {
    transform: translateY(0);
    filter: drop-shadow(0 2px 5px rgba(245, 124, 0, 0.2));
  }
  50% {
    transform: translateY(-2px);
    filter: drop-shadow(0 4px 10px rgba(245, 124, 0, 0.4));
  }
}

@keyframes filter-shimmer {
  0%, 100% {
    transform: translateY(0);
    filter: drop-shadow(0 2px 5px rgba(2, 136, 209, 0.2));
  }
  50% {
    transform: translateY(-2px);
    filter: drop-shadow(0 4px 10px rgba(2, 136, 209, 0.4));
  }
}

#stage {
  --paper: #f6fafb !important;
  --primary: #007685 !important;
  --accent: #d32f2f !important;
  --soft: #e0f2f1 !important;
  --marker: #e0f2f1 !important;
  --text-strong: #142329;
  --text: #455a64;
  --text-meta: #607d8b;
  --blood: #d32f2f;
  --blood-light: #ffebee;
  --teal-deep: #005f6b;
  --teal-light: #e6f6f7;
  --card-bg: #ffffff;
  --card-border: #cfd8dc;
  background:
    radial-gradient(circle at 10% 15%, rgba(211, 47, 47, 0.04) 0%, transparent 400px),
    radial-gradient(circle at 90% 15%, rgba(0, 118, 133, 0.05) 0%, transparent 450px),
    linear-gradient(180deg, #f8fcfe 0%, #f1f7f9 100%);
  font-family: 'Noto Sans JP', 'BIZ UDPGothic', sans-serif;
}

/* 左端アクセントバー（血液の赤 → 透析膜のシアン → 浄化のティール） */
#stage::before {
  width: 14px;
  border-right: 0;
  box-shadow: 2px 0 10px rgba(0, 118, 133, 0.15);
  background: linear-gradient(180deg, #c62828 0%, #e53935 32%, #00acc1 68%, #007685 100%);
}

/* ヘッダー */
#stage .slide-header {
  top: 40px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

#stage #eyebrow {
  display: inline-flex;
  align-items: center;
  padding: 6px 20px;
  border-radius: 999px;
  background: linear-gradient(135deg, #e0f2f1 0%, #b2dfdb 100%);
  color: #005f6b;
  font-size: 19px;
  font-weight: 800;
  letter-spacing: .14em;
  box-shadow: 0 2px 6px rgba(0, 95, 107, 0.08);
}

#stage #brand {
  font-size: 22px;
  font-weight: 900;
  letter-spacing: .22em;
  color: #007685;
}

/* スライドコンテンツ枠 */
#stage #slide-content {
  top: 104px;
  bottom: 110px;
}

/* 見出し */
#stage h1 {
  position: relative;
  border: 0;
  padding: 4px 0 12px 28px;
  margin: 0;
  font-size: 44px;
  font-weight: 900;
  line-height: 1.35;
  color: var(--text-strong);
  letter-spacing: .02em;
}

#stage h1::before {
  content: '';
  position: absolute;
  left: 0;
  top: 6px;
  bottom: 14px;
  width: 8px;
  border-radius: 4px;
  background: linear-gradient(180deg, #e53935 0%, #007685 100%);
}

#stage h1 .section-number {
  display: none;
}

#stage strong {
  color: var(--text-strong);
  font-weight: 800;
}

/* フロー図の全体コンテナ */
#stage .layout-flow .blocks {
  position: relative;
  display: block;
  margin: 22px 0 0;
  height: 540px;
  padding: 0;
}

/* デフォルト矢印を一旦全リセット（下段への意図しない表示を防ぐ） */
#stage .layout-flow .reveal + .reveal .block-body::before,
#stage .layout-flow .reveal + .reveal .block-body::after {
  content: none !important;
}

/* 上段3ブロック（体外循環ルート）と下段2ブロック（除去原理）の配置 */
#stage .layout-flow .blocks > .reveal {
  position: absolute;
  display: block;
  min-width: 0;
}

/* 1. 脱血 */
#stage .layout-flow .blocks > .reveal[data-block="out"] {
  left: 0;
  top: 0;
  width: 480px;
}

/* 2. ダイアライザ（主役・中央） */
#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] {
  left: 558px;
  top: 0;
  width: 580px;
}

/* 3. 返血 */
#stage .layout-flow .blocks > .reveal[data-block="return"] {
  left: 1216px;
  top: 0;
  width: 480px;
}

/* 4. 拡散 */
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] {
  left: 0;
  top: 310px;
  width: 820px;
}

/* 5. 限外濾過 */
#stage .layout-flow .blocks > .reveal[data-block="filtration"] {
  left: 876px;
  top: 310px;
  width: 820px;
}

/* 上段カードの共通ボディ */
#stage .layout-flow .blocks > .reveal[data-block="out"] .block-body,
#stage .layout-flow .blocks > .reveal[data-block="return"] .block-body {
  position: relative;
  height: 228px;
  padding: 22px 28px 20px;
  background: #ffffff;
  border: 1.5px solid #d6e2e6;
  border-radius: 20px;
  box-shadow: 0 10px 24px rgba(20, 35, 41, 0.05);
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  text-align: left;
}

/* 上段カードの上部アクセントライン */
#stage .layout-flow .blocks > .reveal[data-block="out"] .block-body::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: linear-gradient(90deg, #c62828, #ef5350);
}

#stage .layout-flow .blocks > .reveal[data-block="return"] .block-body::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 5px;
  background: linear-gradient(90deg, #00acc1, #00897b);
}

/* 中央ダイアライザ：圧倒的ハイテク感・プレミアムカード */
#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] .block-body {
  position: relative;
  height: 234px;
  margin-top: -3px;
  padding: 22px 30px 20px;
  background: linear-gradient(135deg, #ffffff 0%, #f4fbfb 100%);
  border: 2px solid #00acc1;
  border-radius: 22px;
  animation: pulse-dialyzer 3.5s ease-in-out infinite;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  align-items: flex-start;
  text-align: left;
}

/* ダイアライザの中空糸半透膜グラフィック（微細な透析中空糸のテクスチャ） */
#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] .block-body::after {
  content: '';
  position: absolute;
  right: 20px;
  top: 20px;
  width: 84px;
  height: 84px;
  border-radius: 14px;
  background:
    repeating-linear-gradient(0deg, transparent 0 6px, rgba(0, 172, 193, 0.16) 6px 8px),
    repeating-linear-gradient(90deg, transparent 0 6px, rgba(0, 172, 193, 0.16) 6px 8px),
    #e8f8f9;
  border: 1.5px solid #80deea;
  z-index: 0;
  opacity: 0.85;
}

/* アイコン */
#stage .layout-flow .block-icon {
  width: 50px;
  height: 50px;
  margin-bottom: 10px;
  border-radius: 12px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

#stage .layout-flow .blocks > .reveal[data-block="out"] .block-icon {
  background: #ffebee;
  color: #c62828;
  animation: blood-pulse 2.8s ease-in-out infinite;
}

#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] .block-icon {
  background: #e0f7fa;
  color: #007685;
  z-index: 1;
}

#stage .layout-flow .blocks > .reveal[data-block="return"] .block-icon {
  background: #e8f5e9;
  color: #2e7d32;
}

/* 見出しラベル */
#stage .layout-flow .block-label {
  font-size: 26px;
  font-weight: 800;
  line-height: 1.35;
  color: var(--text-strong);
  margin-bottom: 6px;
  letter-spacing: .02em;
  z-index: 1;
}

/* 本文テキスト */
#stage .layout-flow .block-text {
  font-size: 22px;
  line-height: 1.55;
  color: var(--text);
  z-index: 1;
}

/* 補足ディテール */
#stage .layout-flow .block-detail {
  font-size: 19px;
  font-weight: 700;
  margin-top: 10px;
  padding: 4px 14px;
  border-radius: 8px;
  letter-spacing: .04em;
  display: inline-block;
  z-index: 1;
}

#stage .layout-flow .blocks > .reveal[data-block="out"] .block-detail {
  background: #fff0f0;
  color: #c62828;
  border: 1px solid #ffcdd2;
}

#stage .layout-flow .blocks > .reveal[data-block="dialyzer"] .block-detail {
  background: #e0f2f1;
  color: #005f6b;
  border: 1px solid #80cbc4;
}

#stage .layout-flow .blocks > .reveal[data-block="return"] .block-detail {
  background: #f1f8e9;
  color: #2e7d32;
  border: 1px solid #c8e6c9;
}

/* --------------------------------------------------------------------------
   上段のフロー矢印とアニメーション（out → dialyzer → return のみ！）
   -------------------------------------------------------------------------- */
/* 矢印の線（左から伸びる） */
#stage .motion-flow .reveal[data-block="dialyzer"] .block-body::before,
#stage .motion-flow .reveal[data-block="return"] .block-body::before {
  content: '' !important;
  position: absolute;
  left: -66px;
  top: 50%;
  transform: translateY(-50%);
  width: calc(48px * var(--draw, 1));
  height: 6px;
  border-radius: 3px;
  background: linear-gradient(90deg, #e53935, #00acc1);
  box-shadow: 0 0 10px rgba(0, 172, 193, 0.45);
  z-index: 1;
}

/* 矢印の矢尻（先端で光る） */
#stage .motion-flow .reveal[data-block="dialyzer"]::after,
#stage .motion-flow .reveal[data-block="return"]::after {
  content: '';
  position: absolute;
  left: -24px;
  top: 110px;
  width: 0;
  height: 0;
  border-top: 11px solid transparent;
  border-bottom: 11px solid transparent;
  border-left: 17px solid #00acc1;
  border-right: 0;
  opacity: calc(var(--draw, 1) * 100);
  translate: calc(-42px * (1 - var(--draw, 1))) 0;
  filter: drop-shadow(0 0 calc(12px * var(--spark, 0)) var(--accent));
  z-index: 2;
}

#stage .flow-packet {
  position: absolute;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  background: radial-gradient(circle, #ffffff 20%, #e53935 80%);
  box-shadow: 0 0 18px 8px rgba(229, 57, 53, 0.65);
  z-index: 20;
  pointer-events: none;
}

/* --------------------------------------------------------------------------
   下段2ブロック（拡散・限外濾過）のグラフィカルカード
   -------------------------------------------------------------------------- */
#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-body,
#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-body {
  position: relative;
  height: 160px;
  padding: 20px 28px;
  background: #ffffff;
  border-radius: 20px;
  box-shadow: 0 10px 24px rgba(20, 35, 41, 0.05);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: flex-start;
  text-align: left;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-body {
  border: 1.5px solid #ffe082;
  border-left: 8px solid #f57c00;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-icon {
  position: absolute;
  right: 24px;
  top: 24px;
  margin: 0;
  background: #fff8e1;
  color: #f57c00;
  animation: diffuse-shimmer 3s ease-in-out infinite;
}

#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-body {
  border: 1.5px solid #81d4fa;
  border-left: 8px solid #0288d1;
}

#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-icon {
  position: absolute;
  right: 24px;
  top: 24px;
  margin: 0;
  background: #e1f5fe;
  color: #0288d1;
  animation: filter-shimmer 3s ease-in-out infinite;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-label,
#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-label {
  font-size: 24px;
  font-weight: 800;
  margin-bottom: 6px;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-label {
  color: #b75300;
}

#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-label {
  color: #01579b;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-text,
#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-text {
  font-size: 21px;
  line-height: 1.5;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-detail,
#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-detail {
  font-size: 18px;
  margin-top: 8px;
  padding: 3px 12px;
  border-radius: 6px;
}

#stage .layout-flow .blocks > .reveal[data-block="diffusion"] .block-detail {
  background: #fff3e0;
  color: #e65100;
  border: 1px solid #ffe0b2;
}

#stage .layout-flow .blocks > .reveal[data-block="filtration"] .block-detail {
  background: #e1f5fe;
  color: #01579b;
  border: 1px solid #b3e5fc;
}

/* --------------------------------------------------------------------------
   まとめの一文（note）
   -------------------------------------------------------------------------- */
#stage .slide-note {
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  padding: 16px 28px 16px 40px;
  border-radius: 14px;
  background: linear-gradient(90deg, #e0f2f1 0%, #edf7f6 100%);
  border: 1px solid #b2dfdb;
  border-left: 8px solid #007685;
  color: #004d40;
  font-size: 22px;
  font-weight: 800;
  line-height: 1.4;
  letter-spacing: .02em;
  box-shadow: 0 4px 14px rgba(0, 118, 133, 0.08);
}

#stage .slide-note::before {
  content: none;
}

/* フッター */
#stage .slide-footer {
  bottom: 34px;
  border-top: 1px solid #d9e6e8;
  padding-top: 14px;
  font-size: 19px;
  color: var(--text-meta);
}

#stage #lecture-title {
  font-weight: 700;
  color: #455a64;
}

#stage #slide-number {
  font-weight: 900;
  color: #007685;
}

/* 血液透析の仕組み（LLMにおまかせ）
   コンセプト：透析液の淡い水色を地に、血液＝赤・ダイアライザ＝青緑の2色で「血液の通り道」を見せる。
   左端の帯は赤→青緑のグラデーションで、汚れた血液がきれいになる流れを表す。
   ダイアライザの中で起こる「拡散」「限外濾過」の2つの箱は、点線の枠でひとまとめにする。 */
#stage {
  --paper: #f3f8f9 !important;
  --primary: #173b4f !important;
  --accent: #c9443f !important;
  --soft: #d4ebee !important;
  --marker: #e2f1f3 !important;
  --text-strong: #1f2b33;
  --text: #4f5f68;
  --text-meta: #6b7b83;
  --rule: #d5e2e5;
  --blood: #c9443f;
  --blood-soft: #f8e4e2;
  --teal: #2a8798;
  --teal-soft: #dcf0f2;
  background:
    radial-gradient(circle at 96% 4%, #e1f1f3 0 300px, transparent 301px),
    radial-gradient(circle at 88% 0%, #eaf5f6 0 520px, transparent 521px),
    var(--paper);
}
#stage::before { width: 16px; border-right: 0; box-shadow: none; background: linear-gradient(180deg, #8e2b33 0%, var(--blood) 38%, var(--teal) 100%); }

/* ヘッダー・フッター */
#stage #eyebrow { padding: 6px 20px; border-radius: 999px; background: var(--teal-soft); color: #1d6676; font-weight: 700; letter-spacing: .12em; }
#stage #brand { color: var(--primary); }
#stage .slide-footer { border-top: 1px solid var(--rule); padding-top: 18px; }

/* 見出し：2本線の帯をやめ、左の赤い縦線で区切る。1枚だけなので通し番号は出さない */
#stage .layout-flow h1 { border: 0; border-left: 10px solid var(--blood); border-radius: 2px; padding: 6px 0 6px 30px; margin: 14px 0 0; font-size: 46px; line-height: 1.4; }
#stage .layout-flow h1 .section-number { display: none; }
#stage .layout-flow h1 strong { background: linear-gradient(transparent 62%, var(--blood-soft) 62%); padding: 0 4px; }

/* フロー図：白い角丸の箱。上辺の色で血液（赤）とダイアライザ内（青緑）を分ける */
#stage .layout-flow .blocks { position: relative; isolation: isolate; margin-top: 104px; gap: 0 76px; padding: 0 24px; }
#stage .layout-flow .blocks::after {
  content: 'ダイアライザの中（半透膜の両側を血液と透析液が流れる）';
  position: absolute; grid-column: 2 / 4; grid-row: 1 / 2; inset: -64px -26px -26px; z-index: -1;
  padding: 14px 26px; border: 3px dashed var(--teal); border-radius: 30px; background: rgba(220, 240, 242, .55);
  font-size: 22px; font-weight: 700; letter-spacing: .06em; color: #1d6676; white-space: nowrap; font-feature-settings: 'palt';
}
#stage .layout-flow .block-body { min-height: 300px; padding: 30px 22px 34px; gap: 8px; border: 0; border-top: 10px solid var(--blood); border-radius: 22px; background: #fff; box-shadow: 0 14px 34px rgba(23, 59, 79, .10); }
#stage .layout-flow .reveal[data-block="f2"] .block-body,
#stage .layout-flow .reveal[data-block="f3"] .block-body { border-top-color: var(--teal); }
#stage .layout-flow .block-label { font-size: 32px; letter-spacing: .08em; color: var(--text-strong); }
#stage .layout-flow .block-text { line-height: 1.55; color: var(--text); }
#stage .layout-flow .block-detail { margin-top: 22px; font-size: 22px; line-height: 1.55; color: var(--text-meta); }

/* アイコン：血液の箱は淡い赤、ダイアライザ内の箱は淡い青緑の丸 */
#stage .layout-flow .block-body > .block-icon { width: 108px; height: 108px; margin: -6px 0 8px; background: var(--blood-soft); color: #8e2b33; }
#stage .layout-flow .reveal[data-block="f2"] .block-icon,
#stage .layout-flow .reveal[data-block="f3"] .block-icon { background: var(--teal-soft); color: var(--primary); }
#stage .layout-flow .reveal[data-block="f2"] .block-icon .a,
#stage .layout-flow .reveal[data-block="f3"] .block-icon .a { stroke: var(--teal); }

/* 矢印：太めの赤。箱の間隔に合わせて位置を詰める */
#stage .layout-flow .reveal + .reveal .block-body::before { left: -62px; width: 34px; height: 6px; top: calc(50% - 3px); border-radius: 3px; background: var(--blood); }
#stage .layout-flow .reveal + .reveal .block-body::after { left: -32px; top: calc(50% - 13px); border-width: 13px; border-left: 18px solid var(--blood); border-right: 0; }

/* まとめの一文：淡い青緑の帯 */
#stage .slide-note { padding: 22px 36px 22px 44px; border-top: 0; border-radius: 18px; background: var(--teal-soft); color: var(--text-strong); }
#stage .slide-note::before { top: 0; left: 0; width: 10px; height: 100%; border-radius: 18px 0 0 18px; background: var(--teal); }
#stage .slide-note strong { color: #11505e; }
#stage .has-note .blocks { margin-bottom: 120px; }

theme.css:
/* 血液透析の仕組み（LLMにおまかせデザイン）
   セレクターはすべて #stage から始め、.reveal とアニメーションの仕組みを維持する。 */

#stage {
  --paper: #f4f8fa !important;
  --primary: #144552 !important;
  --accent: #c93b3b !important;
  --soft: #d7eef2 !important;
  --marker: #e3f3f6 !important;
  --text-strong: #182a33;
  --text: #3d525c;
  --text-meta: #5a717d;
  --rule: #cfe0e6;
  --blood: #c93b3b;
  --blood-soft: #fde8e8;
  --diffuse: #0f766e;
  --diffuse-soft: #dff5f2;
  --filter: #0369a1;
  --filter-soft: #e0f2fe;
  --return: #1d6f58;
  --return-soft: #e3f6ef;
  background:
    radial-gradient(circle at 92% 8%, rgba(15, 118, 110, 0.08) 0%, transparent 420px),
    radial-gradient(circle at 8% 88%, rgba(201, 59, 59, 0.05) 0%, transparent 380px),
    linear-gradient(180deg, #f7fbfc 0%, #eef5f8 100%);
}

/* 左端の帯：脱血（赤）→ ダイアライザ浄化（青緑）→ 返血（深緑）のグラデーション */
#stage::before {
  width: 16px;
  border-right: 0;
  box-shadow: 2px 0 12px rgba(20, 69, 82, 0.14);
  background: linear-gradient(180deg, #b91c1c 0%, #dc2626 30%, #0284c7 65%, #0f766e 100%);
}

/* ヘッダー・フッター */
#stage .slide-header {
  top: 46px;
  align-items: center;
}

#stage #eyebrow {
  padding: 6px 22px;
  border-radius: 999px;
  background: linear-gradient(135deg, #dff5f2 0%, #ccebf0 100%);
  border: 1px solid #99d5df;
  color: #0f5257;
  font-size: 20px;
  font-weight: 800;
  letter-spacing: .12em;
}

#stage #brand {
  color: var(--primary);
  font-weight: 900;
  letter-spacing: .24em;
}

#stage #slide-content {
  top: 118px;
  bottom: 132px;
}

#stage .slide-footer {
  bottom: 42px;
  border-top: 1px solid var(--rule);
  padding-top: 16px;
}

#stage #lecture-title {
  color: var(--text);
  font-weight: 700;
}

#stage #slide-number {
  color: var(--primary);
  font-weight: 900;
}

/* 見出し：1枚構成なので通し番号（01）は非表示にし、左のアクセントバーで引き締める */
#stage .layout-flow h1 {
  border: 0;
  border-left: 10px solid var(--blood);
  padding: 6px 0 6px 28px;
  margin: 8px 0 0;
  font-size: 44px;
  line-height: 1.38;
  color: var(--text-strong);
}

#stage .layout-flow h1 .section-number {
  display: none;
}

#stage .layout-flow h1 strong {
  color: #0b4f59;
  background: linear-gradient(transparent 62%, #bfe8ee 62%, #bfe8ee 94%, transparent 94%);
  padding: 0 6px;
}

/* フロー図（4ステップ＋中央2ステップをダイアライザ枠で囲む） */
#stage .layout-flow .blocks {
  position: relative;
  isolation: isolate;
  margin-top: 98px;
  gap: 0 72px;
  padding: 0 20px;
}

#stage .layout-flow .blocks::after {
  content: 'ダイアライザ内部（中空糸半透膜を介して血液と透析液が対向流）';
  position: absolute;
  grid-column: 2 / 4;
  grid-row: 1 / 2;
  inset: -60px -24px -22px;
  z-index: -1;
  padding: 12px 26px;
  border: 3px dashed #16808d;
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(215, 242, 246, 0.72) 0%, rgba(224, 242, 254, 0.5) 100%);
  font-size: 21px;
  font-weight: 800;
  letter-spacing: .05em;
  color: #0f5257;
  white-space: nowrap;
  text-align: center;
  font-feature-settings: 'palt';
}

/* 各ステップのカード */
#stage .layout-flow .block-body {
  min-height: 292px;
  padding: 28px 20px 30px;
  gap: 10px;
  border: 1.5px solid #d5e4ea;
  border-top: 9px solid var(--blood);
  border-radius: 22px;
  background: #ffffff;
  box-shadow: 0 14px 32px rgba(20, 69, 82, 0.09);
}

#stage .layout-flow .reveal[data-block="f2"] .block-body {
  border-top-color: var(--diffuse);
}

#stage .layout-flow .reveal[data-block="f3"] .block-body {
  border-top-color: var(--filter);
}

#stage .layout-flow .reveal[data-block="f4"] .block-body {
  border-top-color: var(--return);
  border-width: 1.5px;
  border-top-width: 9px;
}

/* アイコンの色分け */
#stage .layout-flow .block-body > .block-icon {
  width: 96px;
  height: 96px;
  margin: -4px 0 6px;
  background: var(--blood-soft);
  color: var(--blood);
}

#stage .layout-flow .reveal[data-block="f2"] .block-icon {
  background: var(--diffuse-soft);
  color: var(--diffuse);
}

#stage .layout-flow .reveal[data-block="f2"] .block-icon .a {
  stroke: #0d9488;
}

#stage .layout-flow .reveal[data-block="f2"] .block-icon .d {
  fill: #0d9488;
}

#stage .layout-flow .reveal[data-block="f3"] .block-icon {
  background: var(--filter-soft);
  color: var(--filter);
}

#stage .layout-flow .reveal[data-block="f3"] .block-icon .a {
  stroke: #0284c7;
}

#stage .layout-flow .reveal[data-block="f4"] .block-icon {
  background: var(--return-soft);
  color: var(--return);
}

#stage .layout-flow .reveal[data-block="f4"] .block-icon .a {
  stroke: #10b981;
}

/* カード内テキスト */
#stage .layout-flow .block-label {
  font-size: 27px;
  font-weight: 800;
  letter-spacing: .03em;
  color: var(--text-strong);
}

#stage .layout-flow .block-text {
  font-size: 25px;
  line-height: 1.58;
  color: var(--text);
}

#stage .layout-flow .block-text strong {
  color: var(--text-strong);
  font-weight: 800;
}

/* カード下の補足バッジ */
#stage .layout-flow .block-detail {
  margin-top: 22px;
  padding: 7px 14px;
  border-radius: 10px;
  background: #f8e8e8;
  border: 1px solid #f2c9c9;
  font-size: 20px;
  font-weight: 700;
  line-height: 1.45;
  color: #8f2424;
}

#stage .layout-flow .reveal[data-block="f2"] .block-detail {
  background: #dff5f2;
  border-color: #a7e3db;
  color: #0f5257;
}

#stage .layout-flow .reveal[data-block="f3"] .block-detail {
  background: #e0f2fe;
  border-color: #bae6fd;
  color: #075985;
}

#stage .layout-flow .reveal[data-block="f4"] .block-detail {
  background: #e3f6ef;
  border-color: #b5e6d4;
  color: #165946;
}

/* フロー矢印（motion-flow の --draw / --spark に対応） */
#stage .layout-flow .reveal + .reveal .block-body::before {
  left: -58px;
  width: calc(32px * var(--draw, 1));
  height: 6px;
  top: calc(50% - 3px);
  border-radius: 3px;
  background: var(--accent);
}

#stage .layout-flow .reveal + .reveal .block-body::after {
  left: -30px;
  top: calc(50% - 12px);
  border-width: 12px;
  border-left: 17px solid var(--accent);
  border-right: 0;
}

/* まとめの一文（note） */
#stage .slide-note {
  padding: 20px 34px 20px 44px;
  border-top: 0;
  border-radius: 16px;
  background: linear-gradient(90deg, #dff1f5 0%, #eaf5f7 100%);
  border: 1px solid #b5dce4;
  color: var(--text-strong);
  font-size: 27px;
  box-shadow: 0 6px 18px rgba(20, 69, 82, 0.07);
}

#stage .slide-note::before {
  top: 0;
  left: 0;
  width: 10px;
  height: 100%;
  border-radius: 16px 0 0 16px;
  background: linear-gradient(180deg, var(--blood) 0%, #0f766e 100%);
}

#stage .slide-note strong {
  color: #0b4f59;
}

#stage .has-note .blocks {
  margin-bottom: 116px;
}
